function makeIcon(name){const template=document.createElement("template");template.innerHTML=ICONS[name];return template.content.firstElementChild;}

const projects={
barakah:{title:'Barakah',category:'PERSONAL FINANCE · HACK.MSA, UT AUSTIN',problem:'A financial picture can be scattered across accounts, asset types, and investment tools. Barakah brings those pieces into one personal finance platform.',build:'Built as a 24-hour hackathon MVP, with a Next.js and TypeScript interface, typed REST routes, and a PostgreSQL data layer through Prisma. Plaid connects bank accounts, live pricing powers the wealth engine, and Zoya provides per-holding ethical screening.',detail:'The MVP connects banking, market prices, and screening data in one application. Built during hack.msa at UT Austin.',stack:'Next.js · TypeScript · PostgreSQL · Prisma · Plaid · Zoya · Recharts',link:'https://github.com/BarakahAi/Barakah'},
cougar:{title:'CougarDegree',category:'ACADEMIC PLANNING · CODERED ASTRA',problem:'Choosing classes is only part of degree planning. Students also need a useful sequence that accounts for courses they have already completed.',build:'Built in 36 hours with JavaScript, Node.js, and the Gemini API. Students choose a major, starting semester, and completed classes; the application generates a semester-by-semester plan using public course data from CougarGrades.',detail:'Won the MLH Best Use of DigitalOcean Gradient AI Award. The repository documents 49 supported degree programs, visual progress tracking, and a maximum of five courses per semester. Planning assumes eight full-time semesters and no summer classes.',stack:'JavaScript · Node.js · HTML / CSS · Google Gemini API',link:'https://github.com/Mahmoud-Badi/CougarDegree'},
getdone:{title:'GetDone',category:'PRODUCTIVITY · THE ODIN PROJECT',problem:'A task list should keep projects, priorities, and due dates understandable without putting the interface in the way.',build:'Built with vanilla JavaScript modules and classes, Webpack, and date-fns. Tasks can be created, edited, completed, and deleted, with multiple projects and visual cues for overdue and due-today items.',detail:'Data models, persistence, and rendering stay separate. The DOM layer exposes an onChange callback instead of importing storage. On reload, stored JSON is rebuilt into real class instances, so both data and methods survive.',stack:'JavaScript · Webpack · date-fns · localStorage',link:'https://github.com/Mahmoud-Badi/GetDone'}
};
const dialog=document.querySelector('#project-dialog');
const dialogContent=document.querySelector('#dialog-content');
let lastTrigger;
document.querySelectorAll('.story-trigger').forEach(button=>button.addEventListener('click',()=>{const p=projects[button.dataset.project];lastTrigger=button;dialogContent.replaceChildren();const add=(tag,text,cls)=>{const el=document.createElement(tag);el.textContent=text;if(cls)el.className=cls;dialogContent.append(el);return el;};add('div',p.category,'eyebrow');const title=add('h2',p.title);title.id='dialog-title';add('h3','The problem');add('p',p.problem);add('h3','The build');add('p',p.build);add('h3','Under the hood');add('p',p.detail);add('p',p.stack);const link=add('a','View source','button dark');link.append(makeIcon('ArrowUpRight'));link.href=p.link;link.target='_blank';link.rel='noopener';dialog.showModal();document.body.style.overflow='hidden';}));
document.querySelector('.dialog-close').addEventListener('click',()=>dialog.close());
dialog.addEventListener('click',e=>{const r=dialog.getBoundingClientRect();if(e.target===dialog&&(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom))dialog.close();});
dialog.addEventListener('close',()=>{document.body.style.overflow='';lastTrigger?.focus();});
const output=document.querySelector('#terminal-output'),input=document.querySelector('#command');
const commands={help:'Available commands:\n  about       A quick introduction\n  work        Explore selected projects\n  experience  Where I’ve built\n  skills      My toolkit\n  education   What I’m studying\n  contact     Get in touch\n  funfact     Beyond the keyboard\n  clear       Start fresh',about:'Mahmoud Badi. Software engineer, CS senior at UH, at the University of Houston. Graduating in 2027.',skills:'Frontend: React, Next.js, TypeScript, JavaScript\nBackend: C#, ASP.NET Core, Python, Node.js\nData: PostgreSQL, Azure Cosmos DB, SQL, Prisma\nDesktop & tools: Electron, Git, Azure, xUnit',education:'University of Houston\nBS in Computer Science · Mathematics minor\n2022–2027',contact:'Email: Official.Mahmoud.Badi@gmail.com\nGitHub: github.com/Mahmoud-Badi\nLinkedIn: linkedin.com/in/mahmoud-badi',funfact:'I play soccer and basketball. I also enjoy learning new technologies.',work:'Barakah · CougarDegree · GetDone\nAlso exploring: EconoPulse · Sahel · ReadStack\nTaking you to the projects ↑',experience:'IBM · BECU · FUJIFILM Biotechnologies\nWebRise · iCode School\nTaking you to the experience section ↑',whoami:'Mahmoud Badi — software engineer.',sudo:'This terminal only supports the commands listed in help.'};
const history=[];let historyIndex=0;
function run(raw){const command=raw.trim();if(!command)return;history.push(command);historyIndex=history.length;input.value='';const key=command.toLowerCase();if(key==='clear'){output.replaceChildren();return;}const line=document.createElement('p');const prompt=document.createElement('span');prompt.className='terminal-command';prompt.append(makeIcon('ChevronRight'),document.createTextNode(' ~ '+command));line.append(prompt,document.createElement('br'),document.createTextNode(commands[key]??`Command not found: ${command}. Try help.`));output.append(line);while(output.children.length>40)output.firstElementChild.remove();output.scrollTop=output.scrollHeight;if(key==='work'||key==='experience')document.querySelector(key==='work'?'#work':'#experience').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth'});}
document.querySelector('#terminal-form').addEventListener('submit',e=>{e.preventDefault();run(input.value);});
document.querySelector('#clear-terminal').addEventListener('click',()=>{output.replaceChildren();input.focus();});
document.querySelectorAll('[data-command]').forEach(b=>b.addEventListener('click',()=>{run(b.dataset.command);input.focus({preventScroll:true});}));
input.addEventListener('keydown',e=>{if(e.key==='ArrowUp'){e.preventDefault();historyIndex=Math.max(0,historyIndex-1);input.value=history[historyIndex]??'';}if(e.key==='ArrowDown'){e.preventDefault();historyIndex=Math.min(history.length,historyIndex+1);input.value=history[historyIndex]??'';}});
document.querySelector('#year').textContent=new Date().getFullYear();

// User preference is optional: blocked storage must not break the page.
const themeToggle=document.querySelector('#theme-toggle');
function updateThemeControl(){const dark=document.documentElement.dataset.theme!=='light';themeToggle.replaceChildren(makeIcon(dark?'Sun':'Moon'));themeToggle.setAttribute('aria-label',dark?'Switch to light mode':'Switch to dark mode');document.querySelector('meta[name="theme-color"]').content=dark?'#0b0e12':'#f7f9fc';}
themeToggle.addEventListener('click',()=>{const next=document.documentElement.dataset.theme==='light'?'dark':'light';document.documentElement.dataset.theme=next;try{localStorage.setItem('portfolio-theme',next)}catch(e){}updateThemeControl();});updateThemeControl();
const motionQuery=matchMedia('(prefers-reduced-motion: reduce)'),fineQuery=matchMedia('(pointer: fine)');
const cursor=document.querySelector('#custom-cursor'),portrait=document.querySelector('#portrait-frame');
function resetPointer(){document.body.classList.remove('cursor-active');portrait.style.setProperty('--rx','0deg');portrait.style.setProperty('--ry','0deg');}
window.addEventListener('pointermove',e=>{if(motionQuery.matches||!fineQuery.matches||e.pointerType==='touch')return;if(e.target.closest('video')){document.body.classList.remove('cursor-active');return;}document.body.classList.add('cursor-active');cursor.style.left=e.clientX+'px';cursor.style.top=e.clientY+'px';cursor.classList.toggle('over-link',!!e.target.closest('a,button'));const r=portrait.getBoundingClientRect();if(r.bottom>0){portrait.style.setProperty('--ry',Math.max(-9,Math.min(9,(e.clientX-(r.left+r.width/2))/55))+'deg');portrait.style.setProperty('--rx',Math.max(-7,Math.min(7,-(e.clientY-(r.top+r.height/2))/65))+'deg');}},{passive:true});
window.addEventListener('pointerdown',()=>cursor.classList.add('pressed'));window.addEventListener('pointerup',()=>cursor.classList.remove('pressed'));document.addEventListener('pointerleave',resetPointer);window.addEventListener('blur',resetPointer);window.addEventListener('keydown',e=>{if(e.key==='Tab')resetPointer()});motionQuery.addEventListener('change',resetPointer);fineQuery.addEventListener('change',resetPointer);

// Native dialog provides keyboard focus containment and Escape handling.
const photoDialog=document.querySelector('#photo-dialog');
let photoTrigger;
document.querySelectorAll('.photo-expand').forEach(button=>button.addEventListener('click',()=>{photoTrigger=button;const source=button.querySelector('img'),target=document.querySelector('#photo-full');target.src=source.currentSrc||source.src;target.alt=source.alt;document.querySelector('#photo-caption').textContent=button.closest('figure').querySelector('figcaption').textContent;photoDialog.showModal();document.body.style.overflow='hidden';}));
document.querySelector('.photo-close').addEventListener('click',()=>photoDialog.close());
photoDialog.addEventListener('click',e=>{const r=photoDialog.getBoundingClientRect();if(e.target===photoDialog&&(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom))photoDialog.close();});
photoDialog.addEventListener('close',()=>{document.body.style.overflow='';document.querySelector('#photo-full').removeAttribute('src');photoTrigger?.focus();});
